-- Panel operativo consolidado de indicadores de Recursos Humanos.
create or replace function public.list_hr_operational_indicators(p_token text,p_year integer,p_month integer)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_start date:=make_date(p_year,p_month,1);v_end date:=(v_start+interval '1 month - 1 day')::date;begin v_user:=public.hr_authenticated_user(p_token);
 if v_user.id is null or (v_user.role<>'Administrador' and not(coalesce((v_user.permissions->>'ver_indicadores_rrhh')::boolean,false) or coalesce((v_user.permissions->>'ver_recursos_humanos')::boolean,false))) then return jsonb_build_object('success',false,'error','No posee permiso para consultar indicadores de Recursos Humanos.');end if;
 return jsonb_build_object('success',true,'year',p_year,'month',p_month,
 'headcount',(select jsonb_build_object('active',count(*) filter(where employment_status<>'Desvinculado'),'inactive',count(*) filter(where employment_status='Desvinculado'),'entries',count(*) filter(where hire_date between make_date(p_year,1,1) and make_date(p_year,12,31)),'exits',count(*) filter(where termination_date between make_date(p_year,1,1) and make_date(p_year,12,31)),'rotation_rate',round(100.0*count(*) filter(where termination_date between make_date(p_year,1,1) and make_date(p_year,12,31))/nullif(count(*) filter(where employment_status<>'Desvinculado')+count(*) filter(where termination_date between make_date(p_year,1,1) and make_date(p_year,12,31))/2.0,0),2)) from public.hr_employees),
 'by_direction',coalesce((select jsonb_agg(to_jsonb(x) order by x.employee_count desc,x.direction_name) from(select coalesce(nullif(direction_name,''),'Sin dirección') direction_name,count(*) employee_count,round(sum(monthly_salary),2) salary_cost from public.hr_employees where employment_status<>'Desvinculado' group by direction_name)x),'[]'::jsonb),
 'by_gender',coalesce((select jsonb_agg(to_jsonb(x) order by x.employee_count desc) from(select coalesce(nullif(gender,''),'No especificado') gender,count(*) employee_count from public.hr_employees where employment_status<>'Desvinculado' group by gender)x),'[]'::jsonb),
 'by_age',coalesce((select jsonb_agg(to_jsonb(x) order by x.sort_order) from(select case when birth_date is null then 'No especificada' when extract(year from age(v_end,birth_date))<30 then 'Menos de 30' when extract(year from age(v_end,birth_date))<40 then '30-39' when extract(year from age(v_end,birth_date))<50 then '40-49' when extract(year from age(v_end,birth_date))<60 then '50-59' else '60 o más' end age_range,count(*) employee_count,min(case when birth_date is null then 6 when extract(year from age(v_end,birth_date))<30 then 1 when extract(year from age(v_end,birth_date))<40 then 2 when extract(year from age(v_end,birth_date))<50 then 3 when extract(year from age(v_end,birth_date))<60 then 4 else 5 end) sort_order from public.hr_employees where employment_status<>'Desvinculado' group by age_range)x),'[]'::jsonb),
 'by_status',coalesce((select jsonb_agg(to_jsonb(x) order by x.employee_count desc) from(select coalesce(nullif(payroll_status,''),employment_status) labor_status,count(*) employee_count from public.hr_employees group by coalesce(nullif(payroll_status,''),employment_status))x),'[]'::jsonb),
 'attendance',(select jsonb_build_object('records',count(*),'absences',count(*) filter(where status in('AUSENCIA_JUSTIFICADA','AUSENCIA_NO_JUSTIFICADA')),'unjustified',count(*) filter(where status='AUSENCIA_NO_JUSTIFICADA'),'late',count(*) filter(where status='TARDANZA'),'late_minutes',coalesce(sum(late_minutes),0),'absence_rate',round(100.0*count(*) filter(where status in('AUSENCIA_JUSTIFICADA','AUSENCIA_NO_JUSTIFICADA'))/nullif(count(*),0),2)) from public.hr_attendance_records where work_date between v_start and v_end),
 'recurrent_permissions',coalesce((select jsonb_agg(to_jsonb(x) order by x.case_count desc,x.full_name) from(select e.id employee_id,e.employee_code,e.full_name,e.position_name,e.direction_name,count(*) case_count,sum(c.day_count) total_days from public.hr_employee_cases c join public.hr_employees e on e.id=c.employee_id where c.case_type='PERMISO' and extract(year from c.start_date)=p_year and c.status not in('RECHAZADO','ANULADA') group by e.id having count(*)>=3)x),'[]'::jsonb),
 'pending_vacations',(select count(*) from(select e.id,case when e.hire_date is null then 0 when age(make_date(p_year,12,31),e.hire_date)>=interval '5 years' then 18 else 14 end-coalesce(sum(n.work_days) filter(where n.novelty_type='VACACION' and n.status='APLICADA_NOMINA' and extract(year from n.start_date)=p_year),0) balance from public.hr_employees e left join public.hr_novelties n on n.employee_id=e.id where e.employment_status<>'Desvinculado' group by e.id having case when e.hire_date is null then 0 when age(make_date(p_year,12,31),e.hire_date)>=interval '5 years' then 18 else 14 end-coalesce(sum(n.work_days) filter(where n.novelty_type='VACACION' and n.status='APLICADA_NOMINA' and extract(year from n.start_date)=p_year),0)>0)x),
 'vacancies',(select jsonb_build_object('available',count(*) filter(where status in('VACANTE','CON_RECLUTAMIENTO')),'recruitment',count(*) filter(where status='CON_RECLUTAMIENTO'),'monthly_available',coalesce(sum(monthly_amount) filter(where status in('VACANTE','CON_RECLUTAMIENTO')),0)) from public.hr_vacancies),
 'payroll',(select jsonb_build_object('monthly_cost',coalesce(sum(l.gross_salary),0),'monthly_net',coalesce(sum(l.net_amount),0),'employees',count(distinct l.employee_id)) from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month and b.status<>'BORRADOR'),
 'budget',(select jsonb_build_object('monthly_budget',coalesce(sum(monthly_amount),0),'annual_budget',coalesce(sum(monthly_amount)*12,0),'monthly_execution',coalesce((select sum(l.gross_salary) from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month and b.status<>'BORRADOR'),0),'execution_rate',round(100.0*coalesce((select sum(l.gross_salary) from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month and b.status<>'BORRADOR'),0)/nullif(sum(monthly_amount),0),2)) from public.hr_payroll_budget_lines where budget_year=p_year and active),
 'overtime_by_unit',coalesce((select jsonb_agg(to_jsonb(x) order by x.amount desc) from(select coalesce(nullif(e.direction_name,''),'Sin dirección') direction_name,count(distinct l.employee_id) employees,sum(l.gross_salary) amount from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id join public.hr_employees e on e.id=l.employee_id where b.payroll_year=p_year and b.payroll_month=p_month and b.payroll_type='HORAS_EXTRAS' group by e.direction_name)x),'[]'::jsonb),
 'discipline',(select jsonb_build_object('cases',count(*),'employees',count(distinct employee_id),'repeat_offenders',(select count(*) from(select employee_id from public.hr_employee_cases where case_type='AMONESTACION' and extract(year from start_date)=p_year and status<>'ANULADA' group by employee_id having count(*)>=2)x)) from public.hr_employee_cases where case_type='AMONESTACION' and extract(year from start_date)=p_year and status<>'ANULADA'),
 'retirement_alerts',coalesce((select jsonb_agg(to_jsonb(x) order by x.age_years desc,x.full_name) from(select id employee_id,employee_code,full_name,position_name,direction_name,birth_date,extract(year from age(v_end,birth_date))::integer age_years from public.hr_employees where employment_status<>'Desvinculado' and birth_date is not null and extract(year from age(v_end,birth_date))>=58)x),'[]'::jsonb));end $$;
grant execute on function public.list_hr_operational_indicators(text,integer,integer) to anon,authenticated;
